22	template<bool zero_init=true, typename Engine0, typename Layout0, typename Engine1, typename Layout1, typename Operator>
23	__device__ __forceinline__ void thread_reduce_(Tensor<Engine0, Layout0> const &tensor, Tensor<Engine1, Layout1> &summary, Operator &op) {
24	    static_assert(Layout0::rank == 2, "Only support 2D Tensor");
25	    static_assert(Layout1::rank == 1, "Only support 1D Tensor");
26	    CUTE_STATIC_ASSERT_V(size<0>(summary) == size<0>(tensor));
27	    #pragma unroll
28	    for (int mi = 0; mi < size<0>(tensor); mi++) {
29	        summary(mi) = zero_init ? tensor(mi, 0) : op(summary(mi), tensor(mi, 0));
30	        #pragma unroll
31	        for (int ni = 1; ni < size<1>(tensor); ni++) {
32	            summary(mi) = op(summary(mi), tensor(mi, ni));
33	        }
34	    }
35	
36	}
