46	
47	template<typename Operator>
48	__device__ __forceinline__ float warp_reduce_acc(float &val, Operator &op) {
49	    // Get the thread's position within its group of 4
50	    const int group_id = threadIdx.x / 4;     // Which group of 4 this thread belongs to
51	    const int local_id = threadIdx.x % 4;     // Position within group of 4 (0-3)
52	    
53	    // Only reduce within groups of 4 threads
54	    // Using butterfly pattern
55	    #pragma unroll
56	    for (int offset = 2; offset > 0; offset >>= 1) {
57	        float other = __shfl_down_sync(0xffffffff, val, offset);
58	        if (local_id < offset) {
59	            val = op(val, other);
60	        }
61	    }
62	
63	    // Broadcast the result from thread 0 to all threads in the group
64	    val = __shfl_sync(0xffffffff, val, group_id * 4);
65	    
66	    return val;
67	}
68	
69	template<typename Engine0, typename Layout0, typename Engine1, typename Layout1, typename Tensor2, typename Operator>
70	__device__ __forceinline__ void quad_allreduce_2(Tensor<Engine0, Layout0> &dst, Tensor<Engine1, Layout1> &src, Tensor2 &reduce_tmp, Operator &op) {
71	    // __shared__ float smem[4];  // For 4 warps, we need 4 elements
72	    CUTE_STATIC_ASSERT_V(size(dst) == size(src));
73	    
74	    const int warp_id = threadIdx.x / 32;
75	    const int lane_id = threadIdx.x % 32;
76	    const int row = (threadIdx.x % 32) / 4;
77	
78	    // #if DEBUG
79	    // if (threadIdx.x == 103 && threadIdx.y == 0 && blockIdx.x == 0 && blockIdx.y == 0 && blockIdx.z == 7) {
80	    //     PRINTTENSOR("dst", dst);
81	    // }
82	    // #endif
83	
84	    #pragma unroll
85	    for (int i = 0; i < 1; i++) {
86	        // First do reduction within each group of 4 threads
87	        float val = warp_reduce_acc(src(i), op);
88	        
89	        // Write the result to shared memory for each group's leader
90	        if (lane_id % 4 == 0) {
91	            reduce_tmp(row,warp_id) = val;
92	        }
93	        __syncthreads();
94	        
95	        // Check if thread is one of the first threads in each group of 4 (0,4,8,12,16,20,24,28)
96	        if ((lane_id % 4) == 0) {
97	            // This thread is responsible for reducing its group's values
98	            float group_val = reduce_tmp(row, 0);
99	            #pragma unroll
100	            for (int w = 1; w < 4; w++) {
101	                group_val = op(group_val, reduce_tmp(row, w));
102	            }
103	            reduce_tmp(row, 0) = group_val;
104	        }
105	        __syncthreads();
106	        
107	        // All threads read the final result
108	        dst(i) = reduce_tmp(row,0);
109	
110	        // #if DEBUG
111	        // if (threadIdx.x == 103 && threadIdx.y == 0 && blockIdx.x == 0 && blockIdx.y == 0 && blockIdx.z == 7) {
112	        //     printf("val: %f\n", val);
113	        //     PRINTTENSOR("reduce_tmp", reduce_tmp);
114	        // }
115	        // #endif
116	
117	    }
118	}
119	
120	template<typename Engine0, typename Layout0, typename Engine1, typename Layout1, typename Tensor2, typename Operator>
121	__device__ __forceinline__ void quad_allreduce_(Tensor<Engine0, Layout0> &dst, Tensor<Engine1, Layout1> &src, Tensor2 &reduce_tmp, Operator &op) {
122	    // __shared__ float smem[4];  // For 4 warps, we need 4 elements
123	    CUTE_STATIC_ASSERT_V(size(dst) == size(src));
124	    
125	    const int warp_id = threadIdx.x / 32;
126	    const int lane_id = threadIdx.x % 32;
127	    
128	    #pragma unroll
129	    for (int i = 0; i < size(dst); i++) {
130	        // First do reduction within each group of 4 threads
131	        float val = Allreduce<4>::run(src(i), op);
132	        
133	        // Write the result to shared memory for each group's leader
134	        if (lane_id % 4 == 0) {
135	            reduce_tmp(i,warp_id) = val;
136	        }
137	        __syncthreads();
138	        
139	        // First thread in the first group reads all values and reduces them
140	        if (lane_id == 0) {
141	            float final_val = reduce_tmp(0,0);
142	            #pragma unroll
143	            for (int w = 1; w < 4; w++) {  // For 4 warps
144	                final_val = op(final_val, reduce_tmp(i,w));
145	            }
146	            // Write back the final result
147	            reduce_tmp(i,0) = final_val;
148	        }
149	        __syncthreads();
150	        
151	        // All threads read the final result
152	        // cute::copy(reduce_tmp(0,0), dst(i));
153	        dst(i) = reduce_tmp(i,0);
154	    }
155	}
