157	template<bool zero_init=true, typename Engine0, typename Layout0, typename Engine1, typename Layout1, typename Tensor2, typename Operator>
158	__device__ __forceinline__ void reduce_(Tensor<Engine0, Layout0> const& tensor, Tensor<Engine1, Layout1> &summary, Tensor2 &reduce_tmp, Operator &op) {
159	    thread_reduce_<zero_init>(tensor, summary, op);
160	    quad_allreduce_(summary, summary, reduce_tmp, op);
161	}
