175	template<bool zero_init=true, typename Engine0, typename Layout0, typename Engine1, typename Layout1, typename Tensor2>
176	__device__ __forceinline__ void reduce_max_2(Tensor<Engine0, Layout0> const& tensor, Tensor<Engine1, Layout1> &max, Tensor2 &reduce_tmp){
177	    MaxOp<float> max_op;
178	    reduce_2<zero_init>(tensor, max, reduce_tmp, max_op);
