181	template<bool zero_init=true, typename Engine0, typename Layout0, typename Engine1, typename Layout1>
182	__device__ __forceinline__ void reduce_sum(Tensor<Engine0, Layout0> const& tensor, Tensor<Engine1, Layout1> &sum){
183	    SumOp<float> sum_op;
184	    thread_reduce_<zero_init>(tensor, sum, sum_op);
185	}
186	
187	// Apply the exp to all the elements.
188	template <bool Scale_max=true, typename Engine0, typename Layout0, typename Engine1, typename Layout1>
189	__forceinline__ __device__ void scale_apply_exp2(Tensor<Engine0, Layout0> &tensor, Tensor<Engine1, Layout1> const &max, const float scale) {
190	    static_assert(Layout0::rank == 2, "Only support 2D Tensor");
191	    static_assert(Layout1::rank == 1, "Only support 1D Tensor");
192	    CUTE_STATIC_ASSERT_V(size<0>(max) == size<0>(tensor));
193	    #pragma unroll
194	    for (int mi = 0; mi < size<0>(tensor); ++mi) {
195	        // If max is -inf, then all elements must have been -inf (possibly due to masking).
196	        // We don't want (-inf - (-inf)) since that would give NaN.
197	        // If we don't have float around M_LOG2E the multiplication is done in fp64.
198	        const float max_scaled = max(mi) == -INFINITY ? 0.f : max(mi) * (Scale_max ? scale : float(M_LOG2E));
199	        #pragma unroll
200	        for (int ni = 0; ni < size<1>(tensor); ++ni)  {
201	            // Instead of computing exp(x - max), we compute exp2(x * log_2(e) -
202	            // max * log_2(e)) This allows the compiler to use the ffma
203	            // instruction instead of fadd and fmul separately.
204	            // The following macro will disable the use of fma.
205	            // See: https://github.com/pytorch/pytorch/issues/121558 for more details
206	            // This macro is set in PyTorch and not FlashAttention
207	            #ifdef UNFUSE_FMA
208	                tensor(mi, ni) = exp2f(__fmul_rn(tensor(mi, ni), scale) - max_scaled);
209	            #else
210	                tensor(mi, ni) = exp2f(tensor(mi, ni) * scale - max_scaled);
211	            #endif
212	        }
213	    }
214	}
215	
216	// Apply the exp to all the elements.
217	template <bool zero_init=true, typename Engine0, typename Layout0, typename Engine1, typename Layout1>
218	__forceinline__ __device__ void max_scale_exp2_sum(Tensor<Engine0, Layout0> &tensor, Tensor<Engine1, Layout1> &max, Tensor<Engine1, Layout1> &sum, const float scale) {
219	    static_assert(Layout0::rank == 2, "Only support 2D Tensor");
220	    static_assert(Layout1::rank == 1, "Only support 1D Tensor");
221	    CUTE_STATIC_ASSERT_V(size<0>(max) == size<0>(tensor));
222	    #pragma unroll
223	    for (int mi = 0; mi < size<0>(tensor); ++mi) {
224	        MaxOp<float> max_op;
225	        max(mi) = zero_init ? tensor(mi, 0) : max_op(max(mi), tensor(mi, 0));
226	        #pragma unroll
227	        for (int ni = 1; ni < size<1>(tensor); ni++) {
228	            max(mi) = max_op(max(mi), tensor(mi, ni));
229	        }
230	        max(mi) = Allreduce<4>::run(max(mi), max_op);
231	        // If max is -inf, then all elements must have been -inf (possibly due to masking).
232	        // We don't want (-inf - (-inf)) since that would give NaN.
233	        const float max_scaled = max(mi) == -INFINITY ? 0.f : max(mi) * scale;
234	        sum(mi) = 0;
235	        #pragma unroll
236	        for (int ni = 0; ni < size<1>(tensor); ++ni)  {
237	            // Instead of computing exp(x - max), we compute exp2(x * log_2(e) -
238	            // max * log_2(e)) This allows the compiler to use the ffma
239	            // instruction instead of fadd and fmul separately.
240	            tensor(mi, ni) = exp2f(tensor(mi, ni) * scale - max_scaled);
241	            sum(mi) += tensor(mi, ni);
242	        }
243	        SumOp<float> sum_op;
244	        sum(mi) = Allreduce<4>::run(sum(mi), sum_op);
245	    }
246	}
247	
248	////////////////////////////////////////////////////////////////////////////////////////////////////
249	
250	template <int kNRows>
251	struct Softmax {
252	
253	    using TensorT = decltype(make_tensor<float>(Shape<Int<kNRows>>{}));
254	    TensorT row_max, row_sum;
255	
256	    __forceinline__ __device__ Softmax() {};
257	
258	    template<bool Is_first, bool Check_inf=false, typename Tensor0, typename Tensor1, typename Tensor2>
259	    __forceinline__ __device__ void softmax_rescale_o(Tensor0 &acc_s, Tensor1 &acc_o, Tensor2 &reduce_tmp, float softmax_scale_log2) {
260	        // Reshape acc_s from (MMA=4, MMA_M, MMA_N) to (nrow=(2, MMA_M), ncol=(2, MMA_N))
261	        Tensor scores = make_tensor(acc_s.data(), flash::convert_layout_acc_rowcol(acc_s.layout()));
262	        static_assert(decltype(size<0>(scores))::value == kNRows);
263	        if (Is_first) {
264	            flash::template reduce_max_2</*zero_init=*/true>(scores, row_max, reduce_tmp);
265	            flash::scale_apply_exp2(scores, row_max, softmax_scale_log2);
266	            flash::reduce_sum</*zero_init=*/true>(scores, row_sum);
267	        } else {
268	            Tensor scores_max_prev = make_fragment_like(row_max);
269	            cute::copy(row_max, scores_max_prev);
270	            flash::template reduce_max_2</*zero_init=*/false>(scores, row_max, reduce_tmp);
271	            // Reshape acc_o from (MMA=4, MMA_M, MMA_K) to (nrow=(2, MMA_M), ncol=(2, MMA_K))
272	            Tensor acc_o_rowcol = make_tensor(acc_o.data(), flash::convert_layout_acc_rowcol(acc_o.layout()));
273	            static_assert(decltype(size<0>(acc_o_rowcol))::value == kNRows);
274	            #pragma unroll
275	            for (int mi = 0; mi < size(row_max); ++mi) {
276	                float scores_max_cur = !Check_inf
277	                    ? row_max(mi)
278	                    : (row_max(mi) == -INFINITY ? 0.0f : row_max(mi));
279	                float scores_scale = exp2f((scores_max_prev(mi) - scores_max_cur) * softmax_scale_log2);
280	                row_sum(mi) *= scores_scale;
281	                #pragma unroll
282	                for (int ni = 0; ni < size<1>(acc_o_rowcol); ++ni) { acc_o_rowcol(mi, ni) *= scores_scale; }
283	            }
284	
285	            flash::scale_apply_exp2(scores, row_max, softmax_scale_log2);
286	            // We don't do the reduce across threads here since we don't need to use the row_sum.
287	            // We do that reduce at the end when we need to normalize the softmax.
288	            flash::reduce_sum</*zero_init=*/false>(scores, row_sum);
289	        }
290	    };
291	
292	    template<bool Is_dropout=false, bool Split=false, typename Tensor0, typename Tensor1>
293	    __forceinline__ __device__ TensorT normalize_softmax_lse(Tensor0 &acc_o, Tensor1 &reduce_tmp, float softmax_scale, float rp_dropout=1.0) {
294	        SumOp<float> sum_op;
295	        quad_allreduce_2(row_sum, row_sum, reduce_tmp, sum_op);
296	        TensorT lse = make_fragment_like(row_sum);
297	        Tensor acc_o_rowcol = make_tensor(acc_o.data(), flash::convert_layout_acc_rowcol(acc_o.layout()));
298	        static_assert(decltype(size<0>(acc_o_rowcol))::value == kNRows);
299	        #pragma unroll
300	        for (int mi = 0; mi < size<0>(acc_o_rowcol); ++mi) {
301	            float sum = row_sum(mi);
302	            float inv_sum = (sum == 0.f || sum != sum) ? 1.f : 1.f / sum;
303	            lse(mi) = (sum == 0.f || sum != sum) ? (Split ? -INFINITY : INFINITY) : row_max(mi) * softmax_scale + __logf(sum);
304	            float scale = !Is_dropout ? inv_sum : inv_sum * rp_dropout;
305	            #pragma unroll
306	            for (int ni = 0; ni < size<1>(acc_o_rowcol); ++ni) { acc_o_rowcol(mi, ni) *= scale; }
307	        }
308	        return lse;
309	    };
310	};
311	
312	}  // namespace flash
