161	__forceinline__ __device__ void gemm(Tensor0 &acc, Tensor1 &tCrA, Tensor2 &tCrB, Tensor3 const& tCsA,
162	                            Tensor4 const& tCsB, TiledMma tiled_mma,
163	                            TiledCopyA smem_tiled_copy_A, TiledCopyB smem_tiled_copy_B,
164	                            ThrCopyA smem_thr_copy_A, ThrCopyB smem_thr_copy_B) {
165	    CUTE_STATIC_ASSERT_V(size<1>(tCrA) == size<1>(acc));                     // MMA_M
166	    CUTE_STATIC_ASSERT_V(size<1>(tCrB) == size<2>(acc));                     // MMA_N
167	    CUTE_STATIC_ASSERT_V(size<2>(tCrA) == size<2>(tCrB));                     // MMA_K
168	    Tensor tCrA_copy_view = smem_thr_copy_A.retile_D(tCrA);
169	    CUTE_STATIC_ASSERT_V(size<1>(tCsA) == size<1>(tCrA_copy_view));            // M
170	    Tensor tCrB_copy_view = smem_thr_copy_B.retile_D(tCrB);
171	    CUTE_STATIC_ASSERT_V(size<1>(tCsB) == size<1>(tCrB_copy_view));            // N
172	    if (!A_in_regs) { cute::copy(smem_tiled_copy_A, tCsA(_, _, _0{}), tCrA_copy_view(_, _, _0{})); }
173	    if (!B_in_regs) { cute::copy(smem_tiled_copy_B, tCsB(_, _, _0{}), tCrB_copy_view(_, _, _0{})); }
174	    #pragma unroll
175	    for (int i = 0; i < size<2>(tCrA); ++i) {
176	        if (i < size<2>(tCrA) - 1) {
177	            if (!A_in_regs) { cute::copy(smem_tiled_copy_A, tCsA(_, _, i + 1), tCrA_copy_view(_, _, i + 1)); }
178	            if (!B_in_regs) { cute::copy(smem_tiled_copy_B, tCsB(_, _, i + 1), tCrB_copy_view(_, _, i + 1)); }
179	        }
180	        cute::gemm(tiled_mma, tCrA(_, _, i), tCrB(_, _, i), acc);
181	    }
